import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { login } from '../src/auth.js';
test('right credentials return a session token', () => {
  const db = createDb();
  const token = login(db, 'ann', 'pw-ann', 1000);
  expect(typeof token).toBe('string');
  expect(db.sessions.get(token)).toBe('u1');
});
test('wrong password and unknown user are rejected', () => {
  const db = createDb();
  expect(() => login(db, 'ann', 'nope', 1000)).toThrow('invalid credentials');
  expect(() => login(db, 'ghost', 'x', 1000)).toThrow('invalid credentials');
  expect(db.sessions.size).toBe(0);
});
test('five failures lock the account, even for the right password', () => {
  const db = createDb();
  for (let i = 0; i < 5; i++) expect(() => login(db, 'ann', 'bad', 1000 + i)).toThrow();
  expect(() => login(db, 'ann', 'pw-ann', 2000)).toThrow();
  expect(db.sessions.size).toBe(0);
});

