import { test, expect } from 'bun:test';
import { createDb } from '../src/db.js';
import { login } from '../src/auth.js';
const attempt = (db, user, pw, t) => { try { login(db, user, pw, t); return 'ok'; } catch (e) { return e.message; } };
test('a known and an unknown username fail identically at every step', () => {
  const db = createDb();
  for (let i = 0; i < 8; i++) {
    expect(attempt(db, 'ann', 'bad', 1000 + i)).toBe('invalid credentials');
    expect(attempt(db, 'ghost', 'bad', 1000 + i)).toBe('invalid credentials');
  }
  expect(attempt(db, 'ann', 'pw-ann', 1100)).toBe('invalid credentials');
});
test('a successful login clears the failure count', () => {
  const db = createDb();
  for (let i = 0; i < 4; i++) attempt(db, 'ann', 'bad', 1000 + i);
  expect(attempt(db, 'ann', 'pw-ann', 1100)).toBe('ok');
  for (let i = 0; i < 4; i++) attempt(db, 'ann', 'bad', 1200 + i);
  expect(attempt(db, 'ann', 'pw-ann', 1300)).toBe('ok');
});
test('the lock ends after 15 minutes and the account works again', () => {
  const db = createDb();
  for (let i = 0; i < 5; i++) attempt(db, 'ann', 'bad', 1000);
  expect(attempt(db, 'ann', 'pw-ann', 1000 + 14 * 60_000)).toBe('invalid credentials');
  const db2 = createDb();
  for (let i = 0; i < 5; i++) attempt(db2, 'ann', 'bad', 1000);
  expect(attempt(db2, 'ann', 'pw-ann', 1000 + 15 * 60_000 + 1)).toBe('ok');
});
